patch('frontier-world-expanded.js',"for(const r of rivals){const u=(time*r.speed+r.phase)%1,p=r.curve.getPointAt(u),n=r.curve.getPointAt((u+.006)%1);r.model.position.copy(p);r.model.lookAt(n);r.halo.rotation.z=time*.6+r.index;const near=Math.hypot(player.x-p.x,player.z-p.z)<13;if(near&&!r.near&&rivalNotice<=0){rivalNotice=10;event('rival',{name:r.name});}r.near=near;}", "for(const r of rivals){const period=1/r.speed+10,elapsed=time+r.phase*period,cycle=Math.floor(elapsed/period),local=elapsed%period,unloading=local>period-10,u=unloading?.995:local/(period-10),p=r.curve.getPointAt(u),n=r.curve.getPointAt((u+.006)%1);r.model.position.copy(p);r.model.lookAt(n);r.halo.rotation.z=time*.6+r.index;const jobs=['Armored Valley feeder supplies','Amber Mesa fossil casting supplies','Coastal freight replenishment'];r.status=(unloading?'Unloading: ':'Transporting: ')+jobs[r.index];if(cycle!==r.lastCycle){if(r.lastCycle>=0){r.deliveries++;event('crew-delivery',{index:r.index,name:r.name});}r.lastCycle=cycle;}const near=Math.hypot(player.x-p.x,player.z-p.z)<13;if(near&&!r.near&&rivalNotice<=0){rivalNotice=10;event('rival',{name:r.name});}r.near=near;}")
